# -*- coding: utf-8 -*-import osimport randomimport numpy as npimport pandas as pdimport matplotlibmatplotlib.use("Agg")import matplotlib.pyplot as pltimport torchimport torch.nn as nnfrom torch.utils.data import Dataset, DataLoaderfrom sklearn.metrics import roc_auc_score, log_lossfrom sklearn.preprocessing import LabelEncoder# ============================================================# 1. Basic Utils# ============================================================def set_seed(seed=42):    random.seed(seed)    np.random.seed(seed)    torch.manual_seed(seed)    if torch.cuda.is_available():        torch.cuda.manual_seed_all(seed)def get_device():    device = torch.device("cuda" if torch.cuda.is_available() else "cpu")    print(f"[Device] {device}")    return devicedef make_dir(path):    os.makedirs(path, exist_ok=True)    return path# ============================================================# 2. Data Loading and Preprocessing# ============================================================def load_movielens_ratings(data_path):    df = pd.read_csv(        data_path,        sep="::",        engine="python",        names=["user_id", "movie_id", "rating", "timestamp"]    )    return dfdef build_ctr_label(df, threshold=4):    df = df.copy()    df["label"] = (df["rating"] >= threshold).astype(np.float32)    return dfdef add_time_features(df):    df = df.copy()    df["hour"] = pd.to_datetime(df["timestamp"], unit="s").dt.hour.astype(np.int64)    return dfdef encode_features(df, feature_cols):    df = df.copy()    encoders = {}    for col in feature_cols:        encoder = LabelEncoder()        df[col] = encoder.fit_transform(df[col])        encoders[col] = encoder    field_dims = [int(df[col].max() + 1) for col in feature_cols]    return df, field_dims, encodersdef split_data(df, train_ratio=0.8, valid_ratio=0.1, seed=42):    df = df.sample(frac=1.0, random_state=seed).reset_index(drop=True)    n = len(df)    n_train = int(train_ratio * n)    n_valid = int(valid_ratio * n)    train_df = df.iloc[:n_train].reset_index(drop=True)    valid_df = df.iloc[n_train:n_train + n_valid].reset_index(drop=True)    test_df = df.iloc[n_train + n_valid:].reset_index(drop=True)    return train_df, valid_df, test_dfdef prepare_movielens_data(data_path, feature_cols):    df = load_movielens_ratings(data_path)    df = build_ctr_label(df, threshold=4)    df = add_time_features(df)    df, field_dims, encoders = encode_features(df, feature_cols)    train_df, valid_df, test_df = split_data(df)    return df, train_df, valid_df, test_df, field_dims, encodersdef print_data_info(df, train_df, valid_df, test_df, feature_cols, field_dims):    print("\n[Raw Data]")    print(df.head())    print("\n[Data Info]")    print(f"Number of samples: {len(df)}")    print(f"Positive ratio   : {df['label'].mean():.6f}")    print("\n[Feature Info]")    print(f"Feature columns  : {feature_cols}")    print(f"Field dims       : {field_dims}")    print("\n[Split]")    print(f"Train: {len(train_df)}")    print(f"Valid: {len(valid_df)}")    print(f"Test : {len(test_df)}")# ============================================================# 3. Dataset and DataLoader# ============================================================class CTRDataset(Dataset):    def __init__(self, df, feature_cols, label_col):        self.x = df[feature_cols].values.astype(np.int64)        self.y = df[label_col].values.astype(np.float32)    def __len__(self):        return len(self.y)    def __getitem__(self, idx):        x = torch.from_numpy(self.x[idx])        y = torch.tensor(self.y[idx], dtype=torch.float32)        return x, ydef build_dataloaders(    train_df,    valid_df,    test_df,    feature_cols,    label_col="label",    train_batch_size=1024,    eval_batch_size=2048):    train_loader = DataLoader(        CTRDataset(train_df, feature_cols, label_col),        batch_size=train_batch_size,        shuffle=True,        num_workers=0    )    valid_loader = DataLoader(        CTRDataset(valid_df, feature_cols, label_col),        batch_size=eval_batch_size,        shuffle=False,        num_workers=0    )    test_loader = DataLoader(        CTRDataset(test_df, feature_cols, label_col),        batch_size=eval_batch_size,        shuffle=False,        num_workers=0    )    return train_loader, valid_loader, test_loader# ============================================================# 4. DeepFM Model# ============================================================class DeepFM(nn.Module):    def __init__(        self,        field_dims,        embed_dim=16,        hidden_dims=(128, 64),        dropout=0.2    ):        super().__init__()        self.field_dims = field_dims        self.num_fields = len(field_dims)        offsets = np.array((0, *np.cumsum(field_dims)[:-1]), dtype=np.int64)        self.register_buffer("offsets", torch.tensor(offsets, dtype=torch.long))        self.total_dim = int(sum(field_dims))        self.linear = nn.Embedding(self.total_dim, 1)        self.embedding = nn.Embedding(self.total_dim, embed_dim)        self.mlp = self._build_mlp(            input_dim=self.num_fields * embed_dim,            hidden_dims=hidden_dims,            dropout=dropout        )        self.bias = nn.Parameter(torch.zeros(1))        self.reset_parameters()    @staticmethod    def _build_mlp(input_dim, hidden_dims, dropout):        layers = []        for hidden_dim in hidden_dims:            layers.append(nn.Linear(input_dim, hidden_dim))            layers.append(nn.ReLU())            layers.append(nn.Dropout(dropout))            input_dim = hidden_dim        layers.append(nn.Linear(input_dim, 1))        return nn.Sequential(*layers)    def reset_parameters(self):        nn.init.xavier_uniform_(self.linear.weight.data)        nn.init.xavier_uniform_(self.embedding.weight.data)    def forward(self, x):        x = x + self.offsets.unsqueeze(0)        linear_score = torch.sum(self.linear(x), dim=1)        emb = self.embedding(x)        square_of_sum = torch.sum(emb, dim=1) ** 2        sum_of_square = torch.sum(emb ** 2, dim=1)        fm_score = 0.5 * torch.sum(            square_of_sum - sum_of_square,            dim=1,            keepdim=True        )        deep_input = emb.reshape(emb.size(0), -1)        deep_score = self.mlp(deep_input)        logits = linear_score + fm_score + deep_score + self.bias        pred = torch.sigmoid(logits).squeeze(1)        return preddef build_model(field_dims, device):    model = DeepFM(        field_dims=field_dims,        embed_dim=16,        hidden_dims=(128, 64),        dropout=0.2    ).to(device)    print("\n[Model]")    print(model)    return model# ============================================================# 5. Training and Evaluation# ============================================================def train_one_epoch(model, loader, optimizer, criterion, device):    model.train()    total_loss = 0.0    for x, y in loader:        x = x.to(device)        y = y.to(device)        pred = model(x)        loss = criterion(pred, y)        optimizer.zero_grad()        loss.backward()        optimizer.step()        total_loss += loss.item() * x.size(0)    return total_loss / len(loader.dataset)@torch.no_grad()def evaluate(model, loader, criterion, device):    model.eval()    total_loss = 0.0    preds = []    labels = []    for x, y in loader:        x = x.to(device)        y = y.to(device)        pred = model(x)        loss = criterion(pred, y)        total_loss += loss.item() * x.size(0)        preds.append(pred.detach().cpu().numpy())        labels.append(y.detach().cpu().numpy())    preds = np.concatenate(preds)    labels = np.concatenate(labels)    preds_clip = np.clip(preds, 1e-7, 1.0 - 1e-7)    auc = roc_auc_score(labels, preds)    logloss = log_loss(labels, preds_clip)    avg_loss = total_loss / len(loader.dataset)    return avg_loss, auc, logloss, preds, labelsdef train_model(    model,    train_loader,    valid_loader,    device,    save_dir,    num_epochs=8,    lr=1e-3,    weight_decay=1e-6):    criterion = nn.BCELoss()    optimizer = torch.optim.Adam(        model.parameters(),        lr=lr,        weight_decay=weight_decay    )    best_auc = -1.0    best_path = os.path.join(save_dir, "deepfm_movielens_best.pth")    history = {        "train_loss": [],        "valid_loss": [],        "valid_auc": [],        "valid_logloss": []    }    print("\n[Training]")    for epoch in range(1, num_epochs + 1):        train_loss = train_one_epoch(            model=model,            loader=train_loader,            optimizer=optimizer,            criterion=criterion,            device=device        )        valid_loss, valid_auc, valid_logloss, _, _ = evaluate(            model=model,            loader=valid_loader,            criterion=criterion,            device=device        )        history["train_loss"].append(train_loss)        history["valid_loss"].append(valid_loss)        history["valid_auc"].append(valid_auc)        history["valid_logloss"].append(valid_logloss)        print(            f"Epoch [{epoch:02d}/{num_epochs}] "            f"Train Loss: {train_loss:.6f} | "            f"Valid Loss: {valid_loss:.6f} | "            f"Valid AUC: {valid_auc:.6f} | "            f"Valid LogLoss: {valid_logloss:.6f}"        )        if valid_auc > best_auc:            best_auc = valid_auc            torch.save(model.state_dict(), best_path)    print(f"\n[Best Valid AUC] {best_auc:.6f}")    print(f"[Save Best Model] {best_path}")    return history, best_path, best_aucdef test_model(model, test_loader, device, best_path):    criterion = nn.BCELoss()    model.load_state_dict(torch.load(best_path, map_location=device))    test_loss, test_auc, test_logloss, test_preds, test_labels = evaluate(        model=model,        loader=test_loader,        criterion=criterion,        device=device    )    print("\n[Test Result]")    print(f"Test Loss    : {test_loss:.6f}")    print(f"Test AUC     : {test_auc:.6f}")    print(f"Test LogLoss : {test_logloss:.6f}")    result = {        "test_loss": test_loss,        "test_auc": test_auc,        "test_logloss": test_logloss,        "test_preds": test_preds,        "test_labels": test_labels    }    return result# ============================================================# 6. Recommendation# ============================================================@torch.no_grad()def recommend_topk(model, user_id, candidate_movie_ids, device, topk=10):    model.eval()    rows = []    for movie_id in candidate_movie_ids:        hour = 20        rows.append([user_id, movie_id, hour])    x = torch.tensor(rows, dtype=torch.long).to(device)    scores = model(x).detach().cpu().numpy()    result = pd.DataFrame({        "user_id": user_id,        "movie_id": candidate_movie_ids,        "ctr_score": scores    })    result = result.sort_values(        by="ctr_score",        ascending=False    ).reset_index(drop=True)    return result.head(topk), resultdef run_recommendation(model, df, field_dims, device, save_dir):    user_id = int(df["user_id"].iloc[0])    num_movies = field_dims[1]    candidate_movie_ids = list(range(min(200, num_movies)))    top10, full_rank = recommend_topk(        model=model,        user_id=user_id,        candidate_movie_ids=candidate_movie_ids,        device=device,        topk=10    )    top10_path = os.path.join(save_dir, "top10_movielens.csv")    full_rank_path = os.path.join(save_dir, "full_rank_movielens.csv")    top10.to_csv(top10_path, index=False, encoding="utf-8-sig")    full_rank.to_csv(full_rank_path, index=False, encoding="utf-8-sig")    print("\n[Top-10 Recommendation]")    print(top10)    print(f"\n[Save] {top10_path}")    print(f"[Save] {full_rank_path}")    return top10, full_rank# ============================================================# 7. Visualization# ============================================================def plot_training_curves(history, save_dir):    epochs = np.arange(1, len(history["train_loss"]) + 1)    plt.figure(figsize=(8, 5))    plt.plot(epochs, history["train_loss"], marker="o", label="Train Loss")    plt.plot(epochs, history["valid_loss"], marker="s", label="Valid Loss")    plt.xlabel("Epoch")    plt.ylabel("Loss")    plt.title("Training and Validation Loss")    plt.legend()    plt.grid(True)    save_path = os.path.join(save_dir, "loss_curve.png")    plt.savefig(save_path, dpi=300, bbox_inches="tight")    plt.close()    print(f"[Save Figure] {save_path}")    plt.figure(figsize=(8, 5))    plt.plot(epochs, history["valid_auc"], marker="o", label="Valid AUC")    plt.xlabel("Epoch")    plt.ylabel("AUC")    plt.title("Validation AUC")    plt.legend()    plt.grid(True)    save_path = os.path.join(save_dir, "valid_auc_curve.png")    plt.savefig(save_path, dpi=300, bbox_inches="tight")    plt.close()    print(f"[Save Figure] {save_path}")    plt.figure(figsize=(8, 5))    plt.plot(epochs, history["valid_logloss"], marker="o", label="Valid LogLoss")    plt.xlabel("Epoch")    plt.ylabel("LogLoss")    plt.title("Validation LogLoss")    plt.legend()    plt.grid(True)    save_path = os.path.join(save_dir, "valid_logloss_curve.png")    plt.savefig(save_path, dpi=300, bbox_inches="tight")    plt.close()    print(f"[Save Figure] {save_path}")def plot_prediction_distribution(test_preds, test_labels, save_dir):    pos_preds = test_preds[test_labels == 1]    neg_preds = test_preds[test_labels == 0]    plt.figure(figsize=(8, 5))    plt.hist(neg_preds, bins=50, alpha=0.6, label="Label 0")    plt.hist(pos_preds, bins=50, alpha=0.6, label="Label 1")    plt.xlabel("Predicted CTR")    plt.ylabel("Count")    plt.title("Prediction Distribution")    plt.legend()    plt.grid(True)    save_path = os.path.join(save_dir, "prediction_distribution.png")    plt.savefig(save_path, dpi=300, bbox_inches="tight")    plt.close()    print(f"[Save Figure] {save_path}")def plot_prediction_samples(test_preds, test_labels, save_dir, num_samples=200):    n = min(num_samples, len(test_preds))    plt.figure(figsize=(12, 5))    plt.plot(np.arange(n), test_labels[:n], marker="o", linestyle="none", label="True Label")    plt.plot(np.arange(n), test_preds[:n], marker="x", linestyle="none", label="Predicted CTR")    plt.xlabel("Sample Index")    plt.ylabel("Value")    plt.title("Predicted CTR vs True Label")    plt.legend()    plt.grid(True)    save_path = os.path.join(save_dir, "prediction_samples.png")    plt.savefig(save_path, dpi=300, bbox_inches="tight")    plt.close()    print(f"[Save Figure] {save_path}")def plot_topk_recommendation(top10, save_dir):    plt.figure(figsize=(8, 5))    plt.bar(        top10["movie_id"].astype(str),        top10["ctr_score"]    )    plt.xlabel("Movie ID")    plt.ylabel("Predicted CTR")    plt.title("Top-10 Recommendation Scores")    plt.xticks(rotation=45)    plt.grid(axis="y")    save_path = os.path.join(save_dir, "top10_recommendation_scores.png")    plt.savefig(save_path, dpi=300, bbox_inches="tight")    plt.close()    print(f"[Save Figure] {save_path}")def save_all_figures(history, test_result, top10, save_dir):    plot_training_curves(history, save_dir)    plot_prediction_distribution(        test_preds=test_result["test_preds"],        test_labels=test_result["test_labels"],        save_dir=save_dir    )    plot_prediction_samples(        test_preds=test_result["test_preds"],        test_labels=test_result["test_labels"],        save_dir=save_dir,        num_samples=200    )    plot_topk_recommendation(top10, save_dir)# ============================================================# 8. Save Results# ============================================================def save_experiment_results(best_auc, test_result, save_dir):    result_path = os.path.join(save_dir, "movielens_result.txt")    with open(result_path, "w", encoding="utf-8") as f:        f.write(f"Best Valid AUC: {best_auc:.6f}\n")        f.write(f"Test Loss     : {test_result['test_loss']:.6f}\n")        f.write(f"Test AUC      : {test_result['test_auc']:.6f}\n")        f.write(f"Test LogLoss  : {test_result['test_logloss']:.6f}\n")    print(f"\n[Save Result] {result_path}")    return result_path# ============================================================# 9. Main# ============================================================def main():    set_seed(42)    root = os.path.dirname(os.path.abspath(__file__))    data_path = os.path.join(root, "data/movielens/ml-1m/ratings.dat")    save_dir = make_dir(os.path.join(root, "outputs", "deepfm"))    feature_cols = ["user_id", "movie_id", "hour"]    print("=" * 80)    print("[Project] MovieLens 1M DeepFM CTR Baseline")    print(f"[Data] {data_path}")    print(f"[Save Dir] {save_dir}")    print("=" * 80)    device = get_device()    df, train_df, valid_df, test_df, field_dims, _ = prepare_movielens_data(        data_path=data_path,        feature_cols=feature_cols    )    print_data_info(        df=df,        train_df=train_df,        valid_df=valid_df,        test_df=test_df,        feature_cols=feature_cols,        field_dims=field_dims    )    train_loader, valid_loader, test_loader = build_dataloaders(        train_df=train_df,        valid_df=valid_df,        test_df=test_df,        feature_cols=feature_cols    )    model = build_model(field_dims=field_dims, device=device)    history, best_path, best_auc = train_model(        model=model,        train_loader=train_loader,        valid_loader=valid_loader,        device=device,        save_dir=save_dir,        num_epochs=8,        lr=1e-3,        weight_decay=1e-6    )    test_result = test_model(        model=model,        test_loader=test_loader,        device=device,        best_path=best_path    )    save_experiment_results(        best_auc=best_auc,        test_result=test_result,        save_dir=save_dir    )    top10, _ = run_recommendation(        model=model,        df=df,        field_dims=field_dims,        device=device,        save_dir=save_dir    )    save_all_figures(        history=history,        test_result=test_result,        top10=top10,        save_dir=save_dir    )    print("\n[Done]")if __name__ == "__main__":    main()